  ('12ab511d-8d76-4d14-a3fd-fd6d6c42dde3', 'sanvis-kowsalya-vasudha-mallampet', 'Sanvi''s Kowsalya Vasudha', 'Sanvi Infra Projects Private Limited', 'Mallampet', 'Hyderabad', '2 & 3 BHK', ARRAY[2,3]::int[], 'Apartment', '₹4,X99 – ₹5,X99 per Sft', NULL, NULL, 'Under Construction', 'On Request', 'Near ORR Exit 4A · 4.5 Acres · 5 Towers (G+10) · 15,000 Sft Clubhouse · 100% Vaastu · TG RERA P02200003251', 'Sanvi''s Kowsalya Vasudha is a premium 4.5-acre gated residential township developed by Sanvi Infra Projects in Mallampet, Hyderabad near ORR Exit 4A. Features 5 towers of G+10 floors, a 15,000 sq.ft. clubhouse, and 2 & 3 BHK homes with zero common walls.', ARRAY['15,000 Sft Grand Clubhouse','Swimming Pool & Splash Pool','AC Gymnasium','Indoor Badminton Court','Landscaped Central Park','Children Play Area','Jogging Track','24/7 Security & CCTV','100% DG Power Backup']::text[], '[{"q":"Where is Sanvi''s Kowsalya Vasudha located?","a":"Located near ORR Exit 4A in Mallampet, North-West Hyderabad, with fast connectivity to Bachupally, Miyapur, and HITEC City."},{"q":"Is Sanvi''s Kowsalya Vasudha RERA approved?","a":"Yes, registered with Telangana RERA under TG RERA P02200003251."}]'::jsonb, '{}'::text[], '/assets/sanvi/vasudha-elevation.jpg', NULL, NULL, 'Sanvi''s Kowsalya Vasudha Mallampet | 2 & 3 BHK Price', 'Sanvi''s Kowsalya Vasudha, Mallampet: 2 & 3 BHK luxury apartments (1400-3030 sft), 215 units, 15,000+ sft clubhouse. Get price, floor plans & brochure.', 'https://www.naani.in/projects/sanvis-kowsalya-vasudha-mallampet', '/projects/sanvis-kowsalya-vasudha-mallampet', true, 'published', NULL, '2026-08-02T04:45:01.48811+00:00', 'internal', '2026-08-02T04:45:01.48811+00:00', '2026-11-21T11:12:35.474Z'),
  ('c1baadf9-bd5c-4d6b-9f50-81e40e5e544a', 'aritha-gbr-dhanwin-towers-bowrampet-hyderabad', 'Aritha GBR Dhanwin Towers', 'Aritha Developers LLP', 'Bowrampet', 'Hyderabad', '2 & 3 BHK', '{}'::int[], 'Apartment', 'Price on request', NULL, NULL, 'Ready to Move', NULL, NULL, 'Aritha GBR Dhanwin Towers is a premium gated residential apartment development in Bowrampet, Hyderabad offering 2 & 3 BHK homes from 1165 to 2355 sq.ft. with clubhouse and lifestyle amenities near ORR.', ARRAY['Clubhouse','Swimming Pool','Kids Pool','Gymnasium','Landscaped Gardens','24/7 Security']::text[], '[{"q":"Where is Aritha GBR Dhanwin Towers located?","a":"Located in Bowrampet, Hyderabad near the Outer Ring Road."}]'::jsonb, ARRAY['/assets/aritha-dhanwin/facade-day.jpg','/assets/aritha-dhanwin/elevation-aerial.jpg','/assets/aritha-dhanwin/courtyard-night.jpg','/assets/aritha-dhanwin/garden-day.jpg']::text[], '/assets/aritha-dhanwin/facade-day.jpg', NULL, NULL, 'Aritha GBR Dhanwin Towers Bowrampet | 2 & 3 BHK Apartments', 'Aritha GBR Dhanwin Towers, Bowrampet: 2 & 3 BHK apartments across 4.7 acres and 9 blocks. Get price, floor plans, brochure and site visit. Call now.', 'https://www.naani.in/projects/aritha-gbr-dhanwin-towers-bowrampet-hyderabad', '/projects/aritha-gbr-dhanwin-towers-bowrampet-hyderabad', true, 'published', NULL, '2026-08-04T06:12:58.665689+00:00', 'internal', '2026-08-04T06:12:58.665689+00:00', '2026-11-21T11:12:35.475Z'),
  ('d6cf8fb2-d0b1-4628-8ae4-948218084db2', 'canny-aravindam', 'Canny Aravindam', 'Canny Life Spaces', 'Bowrampet', 'Hyderabad', '2 & 3 BHK Luxury Apartments', ARRAY[2,3]::int[], 'Apartment', 'Price on Request', NULL, NULL, 'Under Construction', '2027-12', '3 Acres · 3 Towers (G+9) · 5-Level Clubhouse · No Common Walls · Near ORR Exit 4A', 'Canny Aravindam is a premium gated residential apartment community developed by Canny Life Spaces across 3 acres in Bowrampet, North-West Hyderabad. The project features 3 towers rising G+9 floors with 340 spacious 2 and 3 BHK apartments, 60% open spaces, no common walls, and a signature 5-level 17,000 sq.ft. clubhouse with 30+ lifestyle amenities.', ARRAY['5-Level Clubhouse (~17,000 sq.ft.)','Swimming Pool & Children Pool','Air-Conditioned Gymnasium','Co-Working Space','Indoor Games Room','Badminton Court','Party Deck & Lawn','Kids Play Area','Yoga & Meditation Zone','Rooftop Garden','Jogging Track','2-Level Car Parking','100% Power Backup','24/7 CCTV & Security Systems','Rainwater Harvesting']::text[], '[{"q":"What is Canny Aravindam?","a":"Canny Aravindam is a luxury 2 and 3 BHK gated apartment community by Canny Life Spaces spread over 3 acres in Bowrampet, Hyderabad, featuring 3 towers with G+9 floors, 340 homes, and a 5-level clubhouse."},{"q":"Where is Canny Aravindam located?","a":"Canny Aravindam is located in Bowrampet, Hyderabad, near ORR Exit 4A, offering quick ~30 min access to Miyapur, Kukatpally, and HITEC City."},{"q":"What configurations are available at Canny Aravindam?","a":"Canny Aravindam offers spacious 2 BHK units ranging from 1,250 to 1,285 sq.ft. and 3 BHK units ranging from 1,505 to 2,300 sq.ft. with no common walls."},{"q":"What is the RERA registration number for Canny Aravindam?","a":"Canny Aravindam is registered with Telangana RERA under registration number P02200007242."},{"q":"What is the expected possession date for Canny Aravindam?","a":"As per current project updates, expected possession is scheduled for December 2027."},{"q":"How can I get the current price for Canny Aravindam?","a":"Pricing is available upon request based on configuration and unit floor. Contact Naani Projects on WhatsApp or call +91 94939 43946 for current price sheets and site visits."}]'::jsonb, ARRAY['/assets/canny-aravindam/canny-aravindam-elevation.jpg','/assets/canny-aravindam/canny-aravindam-clubhouse.jpg','/assets/canny-aravindam/canny-aravindam-brochure.png']::text[], '/assets/canny-aravindam/canny-aravindam-elevation.jpg', NULL, 'https://www.google.com/maps?q=Bowrampet+Hyderabad&output=embed', 'Canny Aravindam, Bowrampet | 2 & 3 BHK Flats', 'Explore Canny Aravindam in Bowrampet, Hyderabad. View 2 and 3 BHK apartment details, amenities, floor plans and RERA information.', 'https://www.naani.in/projects/canny-aravindam', '/projects/canny-aravindam', true, 'published', NULL, '2026-11-21T11:12:35.462Z', 'internal', '2026-11-21T11:12:35.464Z', '2026-11-21T11:12:35.464Z')
