) VALUES
  ('b24e7f10-6665-474b-a80f-79cd3c8d92d1', 'candeur-arbora', 'Candeur Arbora', 'Candeur Constructions', 'Kukatpally', 'Hyderabad', '3 BHK Luxury High-Rise Residences (1,550 - 2,205 Sq.Ft.)', ARRAY[3]::int[], 'Apartment', '₹1.3 Cr Onwards (Subject to Developer Confirmation)', 13000000, 22000000, 'Pre-Launch', '2031-09', '20 Acres · Multiple Towers (G+25) · 1.35 Lakh Sq.Ft. Clubhouse · ~4.3 Acres Central Courtyard · Near IDL Lake', 'Candeur Arbora is a luxury high-rise residential gated township developed by Candeur Constructions spread across 20 acres off Green Hills Road, Kukatpally, Hyderabad. The project features multiple towers rising G+25 floors, ~4.3 acres of open central courtyard, an iconic ~1.35 lakh sq.ft. multi-level clubhouse, and premium 3 BHK luxury residences across four size bands (~1,550 to ~2,205 sq.ft.) near HITEC City, KPHB Colony, and Moosapet Metro.', ARRAY['1.35 Lakh Sq.Ft. Multi-Level Clubhouse','Grand 4.3-Acre Central Open Courtyard','Resort-Style Swimming Pool & Sun Deck','Air-Conditioned Gymnasium & Aerobics Studio','Open-Air Amphitheater with Seating','Outdoor Giant Chess Arena','Children Adventure Playground & Trampoline','Full-Length Jogging & Cycling Track','Yoga & Meditation Lawns with Shaded Gazebo','Multi-Sport Court & Football Turf','Tree-Lined Evening Promenade','100% DG Power Backup for Common Areas & Residences','24/7 Multi-Tier Security with Central CCTV Surveillance','Rainwater Harvesting & Water Softening Plant (WTP)']::text[], '[{"q":"Where is Candeur Arbora located?","a":"Candeur Arbora is strategically situated off Green Hills Road, Kukatpally, Hyderabad, near IDL Lake and opposite Rainbow Vistas, offering quick access to KPHB Colony, Moosapet Metro, HITEC City, and the Financial District."},{"q":"What is the starting price for Candeur Arbora?","a":"Pricing starts provisionally at ₹1.3 Cr onwards for 3 BHK luxury residences, subject to developer confirmation, floor rise, and launch payment plans."},{"q":"What configurations and floor sizes are available?","a":"Candeur Arbora exclusively offers 3 BHK luxury residences across four verified size bands: Compact 3 BHK (~1,550-1,575 sq.ft.), Standard 3 BHK (~1,655-1,830 sq.ft.), Large 3 BHK (~1,830-1,965 sq.ft.), and Premium 3 BHK (~2,048-2,205 sq.ft.)."},{"q":"What are the RERA registration numbers for Candeur Arbora?","a":"Candeur Arbora is registered under Telangana RERA with registration numbers P02200011362 and P02200011363."},{"q":"What is the expected possession timeline?","a":"Expected possession for Candeur Arbora is scheduled around September 2031 (official TG RERA registered timeline)."},{"q":"What lifestyle amenities are available?","a":"The project offers a 1.35 lakh sq.ft. multi-level clubhouse, 4.3-acre central courtyard, swimming pool, open-air amphitheater, adventure play park, giant chess plaza, sports courts, and meditation zones."}]'::jsonb, ARRAY['/assets/candeur-arbora/hero-clubhouse.jpg','/assets/candeur-arbora/aerial-masterview.jpg','/assets/candeur-arbora/masterplan-layout.png','/assets/candeur-arbora/swimming-pool.jpg','/assets/candeur-arbora/central-park.jpg','/assets/candeur-arbora/kids-play-zone.jpg','/assets/candeur-arbora/amphitheater.jpg','/assets/candeur-arbora/jogging-track.jpg','/assets/candeur-arbora/meditation-lawn.webp','/assets/candeur-arbora/giant-chess.jpg','/assets/candeur-arbora/evening-promenade.jpg']::text[], '/og-candeur-arbora.jpg', NULL, 'https://www.google.com/maps?q=IDL+Lake+Kukatpally+Hyderabad&output=embed', 'Candeur Arbora Kukatpally Hyderabad | Luxury 3 BHK High-Rise Apartments', 'Candeur Arbora Kukatpally – 20-acre luxury high-rise gated community with 1.35 lakh sq.ft. clubhouse and 4.3-acre central courtyard. Starting ₹1.3 Cr. Book site visit with Naani Projects.', 'https://www.naani.in/projects/candeur-arbora', '/projects/candeur-arbora', true, 'published', NULL, '2026-11-21T11:12:35.465Z', 'internal', '2026-11-21T11:12:35.465Z', '2026-11-21T11:12:35.465Z'),
  ('a7af6714-ef41-40cd-bd6f-d3e91ba1ddd3', 'pavani-starlit-miyapur', 'Pavani Starlit', 'Sai Sravanthi Infra Projects Private Limited', 'Miyapur', 'Hyderabad', '2, 2.5 & 3 BHK Premium Residences (1,275 - 2,139 Sq.Ft.)', ARRAY[2,3]::int[], 'Apartment', 'Contact for Latest Price', NULL, NULL, 'Under Construction', '2029', '~3 Acres · 3 Towers (G+10) · 45,000+ Sft Advertised Amenities · ~70% Open Space · TG RERA P02400008769 · Maqtha Mahaboobpet, Miyapur', 'Pavani Starlit is a residential apartment development by Sai Sravanthi Infra Projects Private Limited, located in Maqtha Mahaboobpet, Miyapur, Hyderabad. Spread across approximately 3 acres with 3 residential towers (2 Cellars + Stilt + 10 Floors), the community offers 2, 2.5 and 3 BHK apartment configurations (1,275 to 2,139 sq. ft.) and over 45,000 sq. ft. of clubhouse and recreational amenities. Registered under TG RERA ID P02400008769.', ARRAY['45,000+ Sq.Ft. Clubhouse & Recreation Complex','Modern Fully Equipped Gymnasium & Yoga Pavilions','Resort-Style Swimming Pool with Sunken Lounge Deck','Safe Children Splash Pool & Impact Play Areas','Indoor Games Arena (Table Tennis, Billiards, Chess, Carrom)','Dedicated Business Lounge & Co-Working Suites','Conference Facility with High-Speed Connectivity','Multipurpose Celebration Banquet Hall & Party Lawns','Furnished Guest Rooms for Visiting Relatives','Spa & Salon Infrastructure Provision','2-Level Basement Parking with Clear Directional Signage','100% DG Power Backup & Rainwater Harvesting System','24/7 Security Surveillance with Automated Boom Barriers']::text[], '[{"q":"Where is Pavani Starlit located?","a":"Pavani Starlit is located in Maqtha Mahaboobpet, Miyapur, Hyderabad, Telangana 500049, near Miyapur Metro Station and Western Hyderabad employment corridors."},{"q":"Who is the developer of Pavani Starlit?","a":"The project is developed by Sai Sravanthi Infra Projects Private Limited (Pavani Group), an established real estate firm in Hyderabad."},{"q":"What configurations and sizes are available?","a":"The project offers 2 BHK (1,275 – 1,471 sq.ft.), 2.5 BHK (1,348 – 1,590 sq.ft.), and 3 BHK (1,604 – 2,139 sq.ft.) residences."},{"q":"What is the RERA registration number of Pavani Starlit?","a":"Pavani Starlit is registered with Telangana RERA under registration ID TG RERA P02400008769."},{"q":"What is the expected possession timeline?","a":"Expected possession is scheduled for 2029 as per provisional disclosures."},{"q":"What amenities are featured at Pavani Starlit?","a":"The project features over 45,000 sq. ft. of amenities including a clubhouse, swimming pool, gymnasium, business lounge, indoor sports arena, banquet hall, and landscaped gardens."},{"q":"What is the latest price of Pavani Starlit?","a":"Pricing is dynamic and available on request based on available tower inventory, floor rise, and current builder releases. Contact Naani Projects at +91 94939 43946 for official pricing."}]'::jsonb, ARRAY['/og-pavani-starlit.jpg']::text[], '/og-pavani-starlit.jpg', NULL, 'https://www.google.com/maps?q=Miyapur+Hyderabad&output=embed', 'Pavani Starlit Miyapur | 2, 2.5 & 3 BHK Flats in Hyderabad', 'Explore Pavani Starlit Miyapur, Hyderabad. Discover spacious 2, 2.5 & 3 BHK apartments, project details, amenities, location and floor plans.', 'https://www.naani.in/projects/pavani-starlit-miyapur', '/projects/pavani-starlit-miyapur', true, 'published', NULL, '2026-11-21T11:12:35.470Z', 'internal', '2026-11-21T11:12:35.470Z', '2026-11-21T11:12:35.470Z'),
  ('9a02dfa3-edb1-4397-9eac-6abd63df36eb', 'pavani-felicity-nizampet', 'Pavani Felicity', 'Pavani Infra', 'Nizampet', 'Hyderabad', '3 BHK Premium High-Rise Residences (1,561 – 2,514 Sq.Ft.)', ARRAY[3]::int[], 'Apartment', 'Contact for Latest Price', NULL, NULL, 'Under Construction', 'October 2028 (Provisional RERA Target)', '~2.5 Acres · Single High-Rise Tower (2C+S+23F) · Exclusive 3 BHK Community · TG RERA P02200005477 · Near Hill County, Nizampet', 'Pavani Felicity is a premium high-rise residential apartment development by Pavani Infra (promoter Sai Sravanthi Infra Projects Private Limited), located opposite Sapthapadi Convention Centre and adjacent to Hill County in Nizampet, Hyderabad. Spanning approximately 2.16 to 2.5 acres, the project features a single 23-storey residential tower offering spacious 3 BHK apartments ranging from 1,561 to 2,514 sq. ft. with resort lifestyle amenities and ~65% open spaces. Registered under TG RERA ID P02200005477.', ARRAY['Multi-Level Clubhouse & Banquet Hall','Modern Fully Equipped Gymnasium & Fitness Center','Swimming Pool & Safe Kids Splash Pool','Dedicated Co-Working Space & Business Lounge','Indoor Games Room (Table Tennis, Billiards, Chess)','Badminton Court & Half Basketball Practice Court','Cricket Practice Nets & Roller Skating Rink','Children Play Area with Impact Flooring','Landscaped Theme Gardens & Central Sculpture Court','Acupressure Reflexology Walking Path','Senior Citizen Sit-Outs & Outdoor Gazebos','2-Level Basement Parking with Directional Signage','100% DG Emergency Power Backup for Common Areas','24/7 Security Surveillance with Automated Boom Barriers']::text[], '[{"q":"Where is Pavani Felicity located?","a":"Pavani Felicity is situated opposite Sapthapadi Convention Centre, adjacent to Hill County in Nizampet, Hyderabad, Telangana 500090, offering rapid connectivity to Bachupally, Miyapur Metro, and JNTU Kukatpally."},{"q":"Who is the developer of Pavani Felicity?","a":"The project is developed by Pavani Infra and promoted by Sai Sravanthi Infra Projects Private Limited, an established real estate firm in Hyderabad."},{"q":"What configurations are available at Pavani Felicity?","a":"Pavani Felicity exclusively offers 3 BHK premium apartment layouts ranging from 1,561 to 2,514 sq. ft."},{"q":"What is the RERA registration number of Pavani Felicity?","a":"Pavani Felicity is registered with Telangana RERA under registration ID TG RERA P02200005477."},{"q":"What is the expected possession timeline?","a":"The provisional RERA-linked completion timeline is October 2028. Prospective buyers are advised to inspect tower-wise milestones on the official TG RERA portal."},{"q":"What amenities does Pavani Felicity provide?","a":"Amenities include a multi-level clubhouse, swimming pool, gym, co-working lounge, indoor games, badminton court, cricket practice net, skating rink, children play zones, and landscaped open spaces."},{"q":"What is the latest price of Pavani Felicity?","a":"Pricing is dynamic and provided on request based on floor rise, facing, and current builder inventory. Contact Naani Projects at +91 94939 43946 for official pricing."}]'::jsonb, ARRAY['/assets/pavani-felicity/pavani-felicity-elevation-twilight.webp','/assets/pavani-felicity/pavani-felicity-elevation-day.webp','/assets/pavani-felicity/pavani-felicity-tower.webp','/assets/pavani-felicity/pavani-felicity-aerial-courtyard.webp','/assets/pavani-felicity/pavani-felicity-drone-aerial.webp','/assets/pavani-felicity/pavani-felicity-balcony-view.webp','/assets/pavani-felicity/pavani-felicity-masterplan.jpg']::text[], '/assets/pavani-felicity/pavani-felicity-elevation-twilight.webp', NULL, 'https://www.google.com/maps?q=Nizampet+Hyderabad&output=embed', 'Pavani Felicity Nizampet | 3 BHK Flats in Hyderabad', 'Explore Pavani Felicity Nizampet, Hyderabad. Discover spacious 3 BHK apartments, floor plans, clubhouse amenities, location advantages and project details.', 'https://www.naani.in/projects/pavani-felicity-nizampet', '/projects/pavani-felicity-nizampet', true, 'published', NULL, '2026-11-21T11:12:35.470Z', 'internal', '2026-11-21T11:12:35.470Z', '2026-11-21T11:12:35.470Z'),
  ('1b1f3e9d-6133-40f0-81b1-612a637f8d1f', 'pavani-mirai-financial-district', 'Pavani Mirai', 'Pavani Infra', 'Puppalaguda', 'Hyderabad', '4 & 5 BHK Ultra-Luxury Sky Residences & Sky Mansions (7,812 – 16,000 Sq.Ft.)', ARRAY[4,5]::int[], 'Apartment', 'Contact for Latest Price', NULL, NULL, 'Under Construction', 'Provisional RERA Target (Verify Latest Filing)', '~2.46 Acres · Single 55-Storey Mono Skyscraper · 4 Sky Pods at ~720 Ft · 1,01,415 Sft 4-Level Clubhouse · TG RERA P02400007735 · Financial District, Puppalaguda', 'Pavani Mirai is an ultra-luxury 55-storey single mono skyscraper by Pavani Infra (promoter Sai Sravanthi Infra Projects Private Limited), located in the Puppalaguda–Financial District corridor of Hyderabad. Spanning ~2.46 acres with ~75% open spaces, the development features 178 exclusive 4 BHK Sky Residences (~8,000 sq. ft.) and 5 BHK Sky Mansions (~16,000 sq. ft. duplexes), 4 elemental Sky Pods at ~720 feet, 2 rooftop infinity pools, and a 4-level clubhouse spanning 1,01,415 sq. ft. Registered under TG RERA ID P02400007735.', ARRAY['Four Elemental Sky Pods at ~720 Ft Elevation (Terra, Aqua, Ignis, Ventus)','Two Rooftop Panoramic Infinity Swimming Pools','Rooftop Helipad & Private Sky Cabanas','Four-Level Luxury Clubhouse (1,01,415 Sq. Ft.)','350-Seater Multipurpose Banquet & Grand Pre-Function Hall','50-Seater Private Cinema / Preview Theatre','Half Olympic-Size Swimming Pool & Safe Kids Splash Pool','World-Class Gymnasium, Yoga Deck & Meditation Lawns','Private High-Speed Passenger Elevators with Exclusive Lobbies','Indoor Sports (Squash, Badminton, Table Tennis, Billiards)','Virtual Sports Lounges (Virtual Cricket & Golf Simulator)','Dedicated Co-Working Space & Executive Conference Arena','Landscaped Podium with 41-Feature Leisure Garden & Nature Trail','Cricket Turf, Pickleball & Multipurpose Sports Courts','Children Play Zones with Sand Pit & Climbing Wall','Pet Park & Dedicated Pet Grooming Corner','100% DG Emergency Power Backup for Common Areas & Residences','Multi-Tier 24/7 Biometric Security with Automated Access Controls']::text[], '[{"q":"Where is Pavani Mirai located?","a":"Pavani Mirai is situated in the Puppalaguda–Financial District corridor, Hyderabad, Telangana, right beside western Hyderabad premier IT clusters, ORR Exit 4, and Kokapet Neopolis."},{"q":"Who is the developer of Pavani Mirai?","a":"The project is developed by Pavani Infra and promoted by Sai Sravanthi Infra Projects Private Limited."},{"q":"What is the RERA registration number of Pavani Mirai?","a":"Pavani Mirai is registered with Telangana RERA under registration ID TG RERA P02400007735."},{"q":"What configurations and sizes are available at Pavani Mirai?","a":"Pavani Mirai offers ultra-luxury 4 BHK Sky Residences ranging from 7,812 to 8,448 sq. ft. (with dedicated home theatre and 2 maid rooms) and 5 BHK Sky Mansion Duplexes spanning approximately 16,000 sq. ft."},{"q":"What are the Sky Pods at Pavani Mirai?","a":"The project features four elevated elemental Sky Pods perched at approximately 720 feet, offering 360-degree panoramic skyline views, private sky lounges, infinity swimming pools, and rooftop cabanas."},{"q":"What is The Sixth Element architectural philosophy?","a":"The Sixth Element harmonizes the five cosmic elements—Earth, Water, Fire, Air, and Space—with life itself, delivering biophilic architecture, natural cross-ventilation, expansive private decks, and panoramic horizons."},{"q":"How large is the clubhouse at Pavani Mirai?","a":"Pavani Mirai features a four-level luxury clubhouse spanning approximately 1,01,415 sq. ft., housing a 350-seater multipurpose hall, 50-seater private theatre, half Olympic-size pool, squash, badminton, virtual golf, cigar lounge, and wellness spa."},{"q":"What is the latest price of residences at Pavani Mirai?","a":"Pricing is dynamic and provided upon authorized private enquiry based on unit selection, floor rise, and developer release. Contact Naani Projects at +91 94939 43946 for official pricing."},{"q":"What is the expected possession timeline?","a":"Public sources cite completion timelines between late 2028 and early 2029. Prospective buyers should inspect the latest sanctioned milestones on the official TG RERA portal."}]'::jsonb, ARRAY['/assets/pavani-mirai/pavani-mirai-tower-elevation-sunset.webp','/assets/pavani-mirai/pavani-mirai-tower-crown-twilight.webp','/assets/pavani-mirai/pavani-mirai-helipad-rooftop-aerial.jpg','/assets/pavani-mirai/pavani-mirai-sky-pods-crown.jpg','/assets/pavani-mirai/pavani-mirai-terra-pod-lounge.jpg','/assets/pavani-mirai/pavani-mirai-terra-club-lounge.jpg','/assets/pavani-mirai/pavani-mirai-sky-residence-lounge.jpg','/assets/pavani-mirai/pavani-mirai-floor-plate-blueprint.jpg','/assets/pavani-mirai/pavani-mirai-master-layout-plan.webp']::text[], '/assets/pavani-mirai/pavani-mirai-tower-elevation-sunset.webp', NULL, 'https://www.google.com/maps?q=Puppalaguda+Financial+District+Hyderabad&output=embed', 'Pavani Mirai Financial District | Ultra Luxury Apartments Hyderabad', 'Explore Pavani Mirai in Puppalaguda, Hyderabad. Discover exclusive 4 & 5 BHK Sky Residences, Sky Mansions, Sky Pods, clubhouse and luxury amenities.', 'https://www.naani.in/projects/pavani-mirai-financial-district', '/projects/pavani-mirai-financial-district', true, 'published', NULL, '2026-11-21T11:12:35.471Z', 'internal', '2026-11-21T11:12:35.471Z', '2026-11-21T11:12:35.471Z'),
  ('dde69c96-a0e0-4069-9b0d-9ddb692130e6', 'urbanrise-on-cloud-33-bachupally', 'Urbanrise On Cloud 33', 'Urbanrise', 'Bachupally', 'Hyderabad', '3 & 4 BHK Luxury High-Rise Residences (1,353 – 2,021 Sq.Ft.)', ARRAY[3,4]::int[], 'Apartment', 'Starting ₹1.14 Cr* (Contact for Live Inventory & Price Sheet)', 11400000, 21000000, 'Ready to Move & Under Construction', 'Ready to Move (Select Towers) / RERA Target March 2027', '~9.16 Acres · 5 Towers with 33 Floors · ~85,000 Sft Moroccan Clubhouse · ~70,000 Sft Rooftop Amenities across 10 Sky Lounges · Urbanrise Genius Learning Hub · TG RERA P02200003724', 'Urbanrise On Cloud 33 is an expansive 9.16-acre luxury high-rise residential landmark by Urbanrise (promoter Urbanrise Lifestyles Private Limited) on the 200-ft Miyapur–Bachupally Main Road, Hyderabad. The development features 5 iconic towers rising 33 storeys, approximately 70% open green landscape, an ~85,000 sq. ft. Moroccan-themed luxury clubhouse, ~70,000 sq. ft. across 10 rooftop sky lounges, Hammock Park, sensory pathways, the Urbanrise Genius children’s learning hub, and 203+ lifestyle amenities. Over 1,200 families already reside within the vibrant community. Registered under TG RERA ID P02200003724.', ARRAY['Grand 85,000 Sq. Ft. Moroccan-Themed Luxury Clubhouse','70,000 Sq. Ft. Rooftop Amenities across 10 Sky Lounges','Urbanrise Genius Children Learning Hub (Tuition, Robotics, Dance, Music)','Rooftop Aerial Yoga & Meditation Deck with Panoramic Views','Rooftop Party Bar, Barbecue Deck & Open-Air Sky Dining','Resort-Style Swimming Pool with Sunken Lounge & Kids Pool','Hammock Park & Themed Sensory Pathway','Full-Fledged Gymnasium & Aerobics Studio','Indoor Badminton & Squash Courts','Co-Working Lounge in the Park & Sky Co-Working Pods','Outdoor Half-Basketball Court, Table Tennis & Games Room','Landscaped Central Park & Great Lawn','Senior Citizen Plazas & Ladies Kitty Corner','Kids Play Zones, Trampoline Park & Toddlers Sandpit','Rooftop Viewing Deck, Interactive Lounge & Mini Theatre','100% DG Power Backup for Common Areas and Residences','Multi-Tier 24/7 Security with CCTV Surveillance & RFID Access']::text[], '[{"q":"Where is Urbanrise On Cloud 33 located?","a":"Urbanrise On Cloud 33 is prominently located on the 200-ft Miyapur–Bachupally Main Road in Bachupally, North-West Hyderabad, directly connecting to Miyapur Metro Station (10 mins) and Outer Ring Road (ORR Exit 4A/B)."},{"q":"Who is the developer of Urbanrise On Cloud 33?","a":"The project is developed by Urbanrise, a leading South Indian real estate brand, and promoted under Urbanrise Lifestyles Private Limited."},{"q":"What is the TG RERA registration number?","a":"The project is officially registered under TG RERA registration number P02200003724."},{"q":"What configurations and sizes are offered at Urbanrise On Cloud 33?","a":"The project offers well-planned 3 BHK apartments (1,353 to 1,617 sq. ft.) and spacious 4 BHK luxury residences (approximately 2,021 sq. ft.) across 5 high-rise towers of 33 floors each."},{"q":"What is the Moroccan Clubhouse at Urbanrise On Cloud 33?","a":"The community features a grand ~85,000 sq. ft. Moroccan-themed luxury clubhouse with intricate arches, azure swimming pools, indoor sports courts, fitness center, banquet halls, and wellness amenities."},{"q":"What rooftop amenities are available?","a":"Urbanrise On Cloud 33 dedicates ~70,000 sq. ft. across 10 elevated sky lounges on tower terraces, including rooftop yoga, barbecue party bar, co-working in the sky, stargazing, interactive lounges, and mini-theatres."},{"q":"What is the Urbanrise Genius learning hub?","a":"Urbanrise Genius is an integrated children’s enrichment ecosystem within the campus offering after-school tuitions, coding & robotics, music, classical dance, and martial arts training without having to travel outside."},{"q":"Is Urbanrise On Cloud 33 ready to move in?","a":"Yes, select towers and phases have units occupied by over 1,200 families with ready-to-move-in inventory available, while full-phase RERA milestone filings cite completion by March 2027. Buyers should verify specific tower handover schedules."},{"q":"What is the starting price for flats in Urbanrise On Cloud 33?","a":"Developer marketing prices start from ₹1.14 Cr* for 3 BHK configurations. Actual pricing varies by tower, floor rise, orientation, and inventory release. Contact Naani Projects at +91 94939 43946 for current availability and all-inclusive cost sheets."}]'::jsonb, ARRAY['/assets/urbanrise-cloud33/urbanrise-cloud33-elevation-twilight.jpg','/assets/urbanrise-cloud33/urbanrise-cloud33-drone-aerial-day.jpg','/assets/urbanrise-cloud33/urbanrise-cloud33-aerial-night.jpg','/assets/urbanrise-cloud33/urbanrise-cloud33-clubhouse-park.jpg','/assets/urbanrise-cloud33/urbanrise-cloud33-moroccan-clubhouse.jpg','/assets/urbanrise-cloud33/urbanrise-cloud33-master-plan.jpg','/assets/urbanrise-cloud33/urbanrise-cloud33-hammock-park.jpg','/assets/urbanrise-cloud33/urbanrise-cloud33-rooftop-yoga.jpg','/assets/urbanrise-cloud33/urbanrise-cloud33-rooftop-party-bar.jpg','/assets/urbanrise-cloud33/urbanrise-cloud33-rooftop-dining.jpg','/assets/urbanrise-cloud33/urbanrise-cloud33-miyapur-bachupally-road.jpg']::text[], '/assets/urbanrise-cloud33/urbanrise-cloud33-elevation-twilight.jpg', NULL, 'https://www.google.com/maps?q=Urbanrise+On+Cloud+33+Bachupally+Hyderabad&output=embed', 'Urbanrise On Cloud 33 Bachupally | 3 & 4 BHK Flats Hyderabad', 'Explore Urbanrise On Cloud 33 Bachupally, Hyderabad. Discover 3 & 4 BHK apartments, Moroccan clubhouse, 70,000 Sft rooftop amenities, master layout and price details.', 'https://www.naani.in/projects/urbanrise-on-cloud-33-bachupally', '/projects/urbanrise-on-cloud-33-bachupally', true, 'published', NULL, '2026-11-21T11:12:35.473Z', 'internal', '2026-11-21T11:12:35.473Z', '2026-11-21T11:12:35.473Z'),
  ('020097ff-9d78-425a-a22c-e33d543607ef', 'urbanrise-sky-habitat-miyapur', 'Urbanrise Sky Habitat', 'Urbanrise', 'Miyapur', 'Hyderabad', '3 & 4 BHK Luxury High-Rise Residences (1,333 – 2,309 Sq.Ft.)', ARRAY[3,4]::int[], 'Apartment', 'Starting ₹1.32 Cr* (Contact for Live Inventory & Price Sheet)', 13200000, 25000000, 'Under Construction', 'December 2027 (Developer-Advertised; Verify TG RERA Filing)', '~10.6–10.85 Acres · 5 Towers with 42 Floors · 500-Metre Interconnected Skywalk · 15 Sky Lounges · ~1 Lakh Sft Clubhouse · ~70,000 Sft Rooftop Amenities · Ameenpur Lake Views · TG RERA P01100006655', 'Urbanrise Sky Habitat, also marketed as Urbanrise Codename Sky Habitat, is a landmark high-rise residential gated community developed by Urbanrise (Alliance Group) in the Miyapur–Ameenpur corridor of Hyderabad. Spread across ~10.6 to 10.85 acres, the development features 5 iconic towers soaring 42 storeys high, an unprecedented 500-metre interconnected rooftop skywalk bridging across tower crowns, 15 elevated sky lounges, ~1 Lakh sq. ft. of clubhouse infrastructure, ~70,000 sq. ft. of rooftop recreation, ~6 acres of landscaped greenery, Park by the Lake recreation, Urbanrise Genius learning hub, and 200+ lifestyle amenities with panoramic vistas towards Ameenpur Lake. Registered under TG RERA ID P01100006655.', ARRAY['500-Metre Interconnected Rooftop Skywalk Bridging All Towers','15 Elevated Sky Lounges & Stargazing Observation Decks at 42 Floors','Grand 1,00,000 Sq. Ft. Luxury Clubhouse','70,000 Sq. Ft. Rooftop Leisure & Sky Sports Infrastructure','Park by the Lake Landscaped Recreation Enclave & Sensory Trails','Urbanrise Genius Children Learning Hub (Tuition, STEM Robotics, Dance, Music)','Rooftop Panoramic Swimming Pool & Sunbathing Deck','Olympic-Length Swimming Pool & Shallow Kids Splash Pool','Commercial-Grade Gymnasium, Aerobics & Yoga Studio','Indoor Badminton & Squash Courts','Sky Co-Working Pods & Executive Business Lounges','Multipurpose Celebration Banquet Hall & Al-Fresco Dining','Outdoor Sports Courts, Half-Basketball & Table Tennis','Ameenpur Lake Proximity with Natural Horizon Views','100% DG Power Backup for Common Areas and Residences','Multi-Tier 24/7 Security with Biometric Access & CCTV Surveillance']::text[], '[{"q":"Where is Urbanrise Sky Habitat located?","a":"Urbanrise Sky Habitat is strategically located in the Miyapur–Ameenpur residential corridor of North-West Hyderabad, just 5–10 minutes from Miyapur Metro Station, NH-65 Mumbai Highway, and Outer Ring Road (ORR Exit 4A)."},{"q":"Who is the developer of Urbanrise Sky Habitat?","a":"The project is developed by Urbanrise, the premier residential arm of Alliance Group, renowned for delivering over 100,000 homes across South India."},{"q":"What is the TG RERA registration number?","a":"The project is officially registered under Telangana RERA registration number P01100006655."},{"q":"What is the 500-metre Skywalk at Urbanrise Sky Habitat?","a":"The 500-metre interconnected skywalk is a signature architectural sky bridge linking the rooftops of all 5 towers at 42 floors high, creating an elevated jogging, walking, and social observation circuit above the clouds."},{"q":"What configurations and sizes are available?","a":"The project offers well-planned 3 BHK units (1,333 to 1,839 sq. ft.) and expansive 4 BHK luxury residences (2,309 sq. ft.) with panoramic Ameenpur Lake views."},{"q":"How large is the clubhouse and rooftop lifestyle area?","a":"Urbanrise Sky Habitat features approximately 1,00,000 sq. ft. of clubhouse spaces combined with ~70,000 sq. ft. of rooftop amenities across 15 dedicated sky lounges."},{"q":"What is the developer-advertised possession date?","a":"The developer has marketed possession for December 2027. Buyers should independently verify phase-wise handover schedules on the official TG RERA portal."},{"q":"What is the starting price of apartments at Urbanrise Sky Habitat?","a":"Indicative developer marketing prices start around ₹1.32 Cr*. Final all-inclusive costs vary by floor rise, facing, and inventory release. Contact Naani Projects at +91 94939 43946 for official pricing."}]'::jsonb, ARRAY['/assets/urbanrise-sky-habitat/urbanrise-skyhabitat-elevation-day.webp','/assets/urbanrise-sky-habitat/urbanrise-skyhabitat-tower-facade.webp','/assets/urbanrise-sky-habitat/urbanrise-skyhabitat-drone-aerial-day.jpg','/assets/urbanrise-sky-habitat/urbanrise-skyhabitat-rooftop-skywalk.webp','/assets/urbanrise-sky-habitat/urbanrise-skyhabitat-central-courtyard-pool.jpg','/assets/urbanrise-sky-habitat/urbanrise-skyhabitat-master-plan.webp']::text[], '/assets/urbanrise-sky-habitat/urbanrise-skyhabitat-elevation-day.webp', NULL, 'https://www.google.com/maps?q=Urbanrise+Sky+Habitat+Miyapur+Ameenpur+Hyderabad&output=embed', 'Urbanrise Sky Habitat Miyapur | 3 & 4 BHK Apartments Hyderabad', 'Explore Urbanrise Sky Habitat in Miyapur, Hyderabad. View project details, 3 & 4 BHK sizes, amenities, location, 500m skywalk, RERA information and latest prices.', 'https://www.naani.in/projects/urbanrise-sky-habitat-miyapur', '/projects/urbanrise-sky-habitat-miyapur', true, 'published', NULL, '2026-11-21T11:12:35.474Z', 'internal', '2026-11-21T11:12:35.474Z', '2026-11-21T11:12:35.474Z'),
  ('834f997b-e5d2-4004-9de8-b90347a97eff', 'rise-with-9-neopolis-kokapet', 'Rise With 9', 'De Blueoak and P Mangatram Properties LLP', 'Neopolis, Kokapet', 'Hyderabad', '3 & 4 BHK Ultra-Luxury High-Rise Residences', ARRAY[3,4]::int[], 'Apartment', 'Contact for Price', 25000000, 60000000, 'Under Construction', '2029-12-31', 'Neopolis Kokapet · 2 Ultra-Luxury High-Rise Towers (9 North & 9 South) · Double-Height Living Spaces · 18th-Hour Waterfall · Elevated Sky Amenities · TG RERA P02400009942', 'Rise With 9 – The Trilight Residences is an ultra-luxury high-rise residential development located at Plot No. 9, Neopolis Layout, Kokapet, Hyderabad. Spread across two iconic architectural towers (9 North and 9 South), it features large-format 3 & 4 BHK residences with double-height ceiling formats, signature 18th-hour waterfall courtyard, exclusive 9th House clubhouse, panoramic Neopolis skyline vistas, and rapid connectivity to the Financial District and ORR Exit 1A.', ARRAY['18th-Hour Waterfall Courtyard','9th House Private Clubhouse','Infinity Sky Pool & Sun Deck','Double-Height Grand Lobby','High-Tech Gymnasium & Aerobics Studio','Executive Business Lounge & Co-Working Suites','Private Screening Cinema','Landscaped Sky Gardens & Viewing Decks','Badminton & Squash Courts','Multi-Tier 24/7 Security & Access Control']::text[], '[{"q":"What is Rise With 9?","a":"Rise With 9 – The Trilight Residences is an ultra-luxury high-rise residential development located in Neopolis, Kokapet, Hyderabad featuring two architectural towers with large-format 3 & 4 BHK residences, double-height living spaces, and elevated sky amenities."},{"q":"Where is Rise With 9 located?","a":"The project is situated at Plot No. 9, Neopolis Layout, Kokapet, Hyderabad, Telangana – 500075, adjacent to ORR Neopolis Exit 1A."},{"q":"Who is developing Rise With 9?","a":"Rise With 9 is developed by De Blueoak and P Mangatram Properties LLP."},{"q":"Is Rise With 9 RERA approved?","a":"Yes, registered under Telangana RERA registration number P02400009942."}]'::jsonb, ARRAY['/assets/rise-with-9/rise-with-9-trilight-hero.jpg','/assets/rise-with-9/rise-with-9-elevation-night.jpg','/assets/rise-with-9/rise-with-9-18th-hour-waterfall.jpg','/assets/rise-with-9/rise-with-9-clubhouse-9th-house.jpg']::text[], '/assets/rise-with-9/rise-with-9-trilight-hero.jpg', NULL, 'https://www.google.com/maps?q=Neopolis+Kokapet+Hyderabad&output=embed', 'Rise With 9 Neopolis Kokapet | 3 & 4 BHK Luxury Apartments Hyderabad', 'Discover Rise With 9 in Neopolis, Kokapet, Hyderabad. Ultra-luxury 3 & 4 BHK high-rise residences with double-height living, 9th House clubhouse, and sky amenities. TG RERA P02400009942.', 'https://www.naani.in/projects/rise-with-9-neopolis-kokapet', '/projects/rise-with-9', true, 'published', NULL, '2026-11-21T11:12:35.474Z', 'react_page', '2026-11-21T11:12:35.474Z', '2026-11-21T11:12:35.474Z'),
  ('aa43dc28-1c44-4965-9fc8-bf24d7c717de', 'linq-by-raghava', 'LINQ by Raghava', 'Raghava Projects', 'Neopolis, Kokapet', 'Hyderabad', '3 BHK Ultra-Luxury High-Rise Residences', ARRAY[3]::int[], 'Apartment', 'Contact for Latest Pricing', 22000000, 35000000, 'Under Construction', '2030-06-30', '9.2 Acres · Four 58-Storey Towers · 5.5 Lakh Sq.Ft. Lifestyle Amenities · Rooftop Sky Bridge · Near Neopolis Exit 1A · TG RERA P0240011056', 'LINQ by Raghava is an ultra-luxury 3 BHK high-rise gated community developed by Raghava Projects across 9.2 acres in Kokapet near Neopolis, Hyderabad. Soaring 58 storeys across four towers, the development offers over 5.5 lakh sq.ft. of world-class amenities including an iconic elevated sky bridge, rooftop infinity pools, multi-tier sports clubs, and seamless 8-minute connectivity to the Financial District.', ARRAY['5.5 Lakh Sq.Ft. Lifestyle Amenities','Iconic Rooftop Sky Bridge Connecting Towers','Infinity Sky Pool & Observation Deck','Multi-Level Grand Clubhouse','State-of-the-Art Fitness Center & Spa','Indoor Badminton & Tennis Courts','Co-Working Business Lounges','Landscaped Central Greens & Jogging Trails','Children''s Adventure Play Park','24/7 Multi-Tier Smart Security']::text[], '[{"q":"What is LINQ by Raghava?","a":"LINQ by Raghava is an ultra-luxury 3 BHK residential community developed by Raghava Projects across 9.2 acres in Kokapet near Neopolis with four 58-storey towers."},{"q":"Where is LINQ by Raghava located?","a":"LINQ by Raghava is located in Kokapet, Neopolis, Hyderabad, Telangana – 500075, within 5 minutes of Kokapet ORR Exit and 8 minutes of Financial District."},{"q":"Is LINQ by Raghava RERA approved?","a":"Yes, registered with Telangana RERA under registration number P0240011056."}]'::jsonb, ARRAY['/assets/linq-by-raghava/linq-by-raghava-elevation-hero.jpg','/assets/linq-by-raghava/linq-by-raghava-sky-bridge.jpg','/assets/linq-by-raghava/linq-by-raghava-master-layout-plan.png','/assets/linq-by-raghava/linq-by-raghava-sky-amenities-rooftop.jpg']::text[], '/assets/linq-by-raghava/linq-by-raghava-elevation-hero.jpg', NULL, 'https://www.google.com/maps?q=Neopolis+Kokapet+Hyderabad&output=embed', 'LINQ by Raghava Kokapet Neopolis | Luxury 3 BHK Apartments Hyderabad', 'Explore LINQ by Raghava in Neopolis Kokapet, Hyderabad. Ultra-luxury 3 BHK high-rise apartments across 4 towers of 58 storeys with 5.5L sq.ft. amenities. TG RERA P0240011056.', 'https://www.naani.in/projects/linq-by-raghava', '/projects/linq-by-raghava', true, 'published', NULL, '2026-11-21T11:12:35.474Z', 'react_page', '2026-11-21T11:12:35.474Z', '2026-11-21T11:12:35.474Z'),
  ('70b8d778-15a7-4d4d-a8b0-b5debec16963', 'candeur-eternia-bachupally-hyderabad', 'Candeur Eternia', 'Candeur Constructions', 'Bachupally', 'Hyderabad', '2, 2.5 & 3 BHK Premium High-Rise Residences', ARRAY[2,3]::int[], 'Apartment', '₹85 Lakhs – ₹1.65 Cr', 8500000, 16500000, 'Under Construction', '2028-12-31', '73,000 Sq.Ft. 5-Level Clubhouse · Premium 2 & 3 BHK Formats · Near Miyapur Metro & ORR · TG RERA P02200010709', 'Candeur Eternia is a landmark premium high-rise gated residential community developed by Candeur Constructions in Bachupally, Hyderabad. Featuring premium 2, 2.5 and 3 BHK residences, the project includes an iconic 73,000 sq.ft. multi-level clubhouse, rooftop infinity pool, landscaped open podiums, and rapid connectivity to Miyapur Metro, Kukatpally, and the Outer Ring Road.', ARRAY['73,000 Sq.Ft. 5-Level Clubhouse','Rooftop Swimming Pool & Kids Pool','Modern Gymnasium & Yoga Studio','Indoor Badminton & Squash Courts','Children''s Adventure Play Area','Landscaped Theme Gardens','Jogging & Cycling Tracks','EV Charging Infrastructure','100% DG Power Backup','24/7 Security with CCTV Surveillance']::text[], '[{"q":"Where is Candeur Eternia located?","a":"Candeur Eternia is located in Bachupally, Hyderabad with seamless connectivity to Miyapur Metro, HITEC City, Kukatpally and ORR."},{"q":"What configurations are available?","a":"Premium 2 BHK (1462 / 1546 sft), 3B2T (1590 / 1619 sft) and 3B3T (1711 / 1874 / 2004 / 2192 sft) apartments."},{"q":"Is the project RERA approved?","a":"Yes. Candeur Eternia is RERA approved with registration number P02200010709."}]'::jsonb, ARRAY['/assets/candeur-eternia/hero.png','/assets/candeur-eternia/clubhouse.png','/assets/candeur-eternia/towers.png','/assets/candeur-eternia/masterplan.png','/assets/candeur-eternia/payment-plan.png']::text[], '/assets/candeur-eternia/hero.png', NULL, 'https://www.google.com/maps?q=Bachupally+Hyderabad&output=embed', 'Candeur Eternia Bachupally Hyderabad | Premium Apartments | Naani Projects', 'Explore Candeur Eternia in Bachupally, Hyderabad featuring premium 2, 2.5 & 3 BHK apartments with luxury amenities, excellent connectivity, and world-class lifestyle features. TG RERA P02200010709.', 'https://www.naani.in/projects/candeur-eternia-bachupally-hyderabad', '/projects/candeur-eternia-bachupally-hyderabad', true, 'published', NULL, '2026-11-21T11:12:35.474Z', 'react_page', '2026-11-21T11:12:35.474Z', '2026-11-21T11:12:35.474Z'),
  ('7af9c23c-5d95-418a-bfc3-bb8c7485707b', 'godrej-kukatpally-hyderabad', 'Godrej Kukatpally Hyderabad', 'Godrej Properties', 'Kukatpally', 'Hyderabad', '3 & 4 BHK Ultra-Luxury High-Rise Residences', ARRAY[3,4]::int[], 'Apartment', '₹2.50 Cr Onwards (Contact for Live Price Sheet)', 25000000, 45000000, 'Pre-Launch', '2030-12-31', '7.8 Acres · 2 Iconic Towers (G+46 Storeys) · Near KPHB Phase IV & HITEC City · Ultra-Luxury Signature Living', 'Godrej Kukatpally Hyderabad is an ultra-luxury high-rise residential landmark developed by Godrej Properties across 7.8 acres in KPHB Phase IV, Kukatpally, Hyderabad. Soaring G+46 floors across two iconic towers, the development offers spacious 3 & 4 BHK residences, world-class resort amenities, zero common walls, and prime connectivity to HITEC City, Cyber Towers, and the Financial District.', ARRAY['Grand Multi-Level Clubhouse','Olympic-Length Swimming Pool & Pool Deck','State-of-the-Art Gymnasium & Fitness Center','Dedicated Yoga & Meditation Lawn','Indoor Squash & Badminton Courts','Children''s Creative Play Park','Landscaped Zen Gardens','Jogging Track & Walking Trails','Multi-Tier Intelligent Security','100% Power Backup & EV Charging']::text[], '[{"q":"Where is Godrej Kukatpally located?","a":"Godrej Kukatpally is located at KPHB Phase IV, Kukatpally, Hyderabad with metro connectivity and direct access to HITEC City and the Financial District."},{"q":"What configurations are available?","a":"Ultra-luxury 3 & 4 BHK apartments across 2 high-rise G+46 towers."},{"q":"Who is the developer of Godrej Kukatpally?","a":"The project is developed by Godrej Properties, one of India’s most trusted real estate developers."}]'::jsonb, ARRAY['/assets/godrej-kukatpally/hero.jpg','/assets/godrej-kukatpally/floor-plan.png','/assets/godrej-kukatpally/aerial.png','/assets/godrej-kukatpally/masterplan.png']::text[], '/assets/godrej-kukatpally/hero.jpg', NULL, 'https://www.google.com/maps?q=KPHB+Phase+IV+Kukatpally+Hyderabad&output=embed', 'Godrej Kukatpally Hyderabad | Luxury 3 & 4 BHK Apartments', 'Explore Godrej Kukatpally Hyderabad, an ultra-luxury high-rise residential project offering premium 3 & 4 BHK apartments near HITEC City with world-class amenities and excellent connectivity.', 'https://www.naani.in/projects/godrej-kukatpally-hyderabad', '/projects/godrej-kukatpally-hyderabad', true, 'published', NULL, '2026-11-21T11:12:35.474Z', 'react_page', '2026-11-21T11:12:35.474Z', '2026-11-21T11:12:35.474Z'),
  ('45caef80-c07b-4222-887b-8fa4fcd2d2ac', 'trump-towers-hyderabad-kokapet', 'Trump Towers Hyderabad', 'Ira The Edge Developers LLP / Tribeca Developers', 'Golden Mile, Kokapet', 'Hyderabad', '3.5, 4, 4.5 & 6 BHK Branded Sky Residences', ARRAY[3,4,6]::int[], 'Apartment', '₹4.50 Cr – ₹12.00 Cr+', 45000000, 120000000, 'Under Construction', '2031-05-15', '4.04 Acres · Twin 65-Storey Skyscraper Towers · Private Elevators · Three-Level Floating Trump Club · Golden Mile Kokapet · TG RERA P02400010871', 'Trump Towers Hyderabad is an ultra-luxury branded residential development located in Golden Mile, Kokapet, Hyderabad. Developed by Ira The Edge Developers LLP with Tribeca Developers across ~4.04 acres, it features two iconic 65-storey towers offering 3.5, 4, 4.5, and 6 BHK sky residences with private elevator vestibules, expansive decks, and a signature three-level floating Trump Club suspended between the towers.', ARRAY['Three-Level Floating Cantilevered Trump Club','Infinity-Edge Sky Pool & Private Cabanas','Specialty Fine Dining Restaurant & Cigar Lounge','Executive Business Centre & Boardrooms','Full-Service Spa & Wellness Salons','Private Screening Theatre & Entertainment Arcades','High-Tech Gymnasium & Yoga Studios','Private Elevator Access to Every Unit','Multi-Tier 24/7 Concierge & Security Services','Landscaped Golden Mile Greens']::text[], '[{"q":"What is Trump Towers Hyderabad?","a":"Trump Towers Hyderabad is an ultra-luxury branded residential development located in Golden Mile, Kokapet, Hyderabad featuring two iconic 65-storey towers offering 3.5, 4, 4.5, and 6 BHK sky residences with private elevators and a three-level floating Trump Club."},{"q":"Where is Trump Towers Hyderabad located?","a":"Trump Towers Hyderabad is located in Golden Mile, Kokapet, Gandipet Mandal, Hyderabad, Telangana – 500075, adjacent to Neopolis and Financial District with direct connectivity to ORR Exit 1A."},{"q":"Who is the developer of Trump Towers Hyderabad?","a":"The official developer and promoter registered under Telangana RERA is Ira The Edge Developers LLP, with Tribeca Developers as official development partner."},{"q":"What is the RERA registration number for Trump Towers Hyderabad?","a":"The project is registered with Telangana RERA under registration number P02400010871."}]'::jsonb, ARRAY['/assets/trump-towers/hero.jpg','/assets/trump-towers/elevation-upward.jpg','/assets/trump-towers/elevation-diagram.png','/assets/trump-towers/entrance.png','/assets/trump-towers/logo-card.png']::text[], '/assets/trump-towers/hero.jpg', NULL, 'https://www.google.com/maps?q=Kokapet+Golden+Mile+Hyderabad&output=embed', 'Trump Towers Hyderabad Kokapet | Luxury Branded Residences', 'Explore Trump Towers Hyderabad in Kokapet''s Golden Mile. Discover 65-storey twin towers, private elevators, large-format residences, the three-level Trump Club and West Hyderabad connectivity. TG RERA P02400010871.', 'https://www.naani.in/projects/trump-towers-hyderabad-kokapet', '/projects/trump-towers-hyderabad-kokapet', true, 'published', NULL, '2026-11-21T11:12:35.474Z', 'react_page', '2026-11-21T11:12:35.474Z', '2026-11-21T11:12:35.474Z')
